    function clampPosition(right, bottom) {
      const viewportWidth = window.innerWidth || 1024;
      const viewportHeight = window.innerHeight || 768;
      const maxRight = Math.max(6, viewportWidth - PET_WIDTH);
      const maxBottom = Math.max(6, viewportHeight - PET_HEIGHT);
      return {
        right: Math.min(Math.max(right, 6), maxRight),
        bottom: Math.min(Math.max(bottom, 6), maxBottom),
      };
    }

    function loadPosition() {
      try {
        const raw = window.localStorage.getItem(POS_KEY);
        if (raw) {
          const value = JSON.parse(raw);
          if (
            value &&
            Number.isFinite(value.right) &&
            Number.isFinite(value.bottom)
          ) {
            return clampPosition(value.right, value.bottom);
          }
        }
      } catch (error) {
        /* storage can be unavailable; fall through to the default corner */
      }
      return clampPosition(24, 16);
    }

    function savePosition(value) {
      try {
        window.localStorage.setItem(POS_KEY, JSON.stringify(value));
      } catch (error) {
        /* the pet simply forgets its corner when storage is blocked */
      }
    }

